import fs from 'node:fs';
import path from 'node:path';
import type Database from 'better-sqlite3';

/**
 * Applies every `drizzle/*.sql` file exactly once, in filename order.
 * Files are plain SQL (generated by drizzle-kit or written by hand) so the
 * runtime needs no extra tooling to boot.
 */
export function applyMigrations(sqlite: Database.Database, migrationsDir: string): string[] {
  sqlite.exec(
    'CREATE TABLE IF NOT EXISTS _migrations (name TEXT PRIMARY KEY, applied_at TEXT NOT NULL)'
  );
  const appliedRows = sqlite.prepare('SELECT name FROM _migrations').all() as Array<{ name: string }>;
  const applied = new Set(appliedRows.map((r) => r.name));

  if (!fs.existsSync(migrationsDir)) {
    throw new Error(`Migrations directory not found: ${migrationsDir}`);
  }
  const files = fs
    .readdirSync(migrationsDir)
    .filter((file) => file.endsWith('.sql'))
    .sort();
  if (files.length === 0) {
    throw new Error(`No .sql migrations found in ${migrationsDir}`);
  }

  const newlyApplied: string[] = [];
  const record = sqlite.prepare('INSERT INTO _migrations (name, applied_at) VALUES (?, ?)');
  for (const file of files) {
    if (applied.has(file)) continue;
    const sql = fs.readFileSync(path.join(migrationsDir, file), 'utf8');
    const run = sqlite.transaction(() => {
      sqlite.exec(sql);
      record.run(file, new Date().toISOString());
    });
    run();
    newlyApplied.push(file);
  }
  return newlyApplied;
}
